vectors.spec:
name "ex"
bin "ex"
flag "--log-level <level>" overrides="--trace" {
  choices "debug" "info"
}
flag "--trace"

name "ex"
bin "ex"
flag "--format <format>" env="EX_FORMAT" {
  requires_if "json" "--schema"
}
flag "--schema <file>"

name "ex"
bin "ex"
flag "--format <format>" default="json" {
  requires_if "json" "--schema"
}
flag "--schema <file>"
